        addBlock("iron_cobblegen_block", () -> new CobbleGeneratorBlock(BlockBehaviour.Properties.of().mapColor(MapColor.STONE).strength(1.2F, 1000.0F).lightLevel(state -> 7).requiresCorrectToolForDrops().sound(SoundType.METAL), 20, 64));
        addBlock("diamond_cobblegen_block", () -> new CobbleGeneratorBlock(BlockBehaviour.Properties.of().mapColor(MapColor.STONE).strength(1.5F, 1000.0F).lightLevel(state -> 7).requiresCorrectToolForDrops().sound(SoundType.METAL), 10, 64));
        addBlock("emerald_cobblegen_block", () -> new CobbleGeneratorBlock(BlockBehaviour.Properties.of().mapColor(MapColor.STONE).strength(2.5F, 1000.0F).lightLevel(state -> 7).requiresCorrectToolForDrops().sound(SoundType.METAL), 1, 64));
